"use client"

import { forwardRef, useId, useImperativeHandle, type ReactNode } from "react"

import { DAY_NAMES } from "./cron"
import { useCronInput, type UseCronInputOptions } from "./use-cron-input"

export type CronLayout = "expression" | "builder"

export interface CronInputProps extends UseCronInputOptions {
  /** Visible label. Supply this or `aria-label` — a field with neither has no accessible name. */
  label?: ReactNode
  /** Helper text under the field. Replaced by the error message while one is showing. */
  hint?: ReactNode
  /** `expression` for engineers, `builder` for everyone else. */
  layout?: CronLayout
  /** Show the plain-English reading. Default true. */
  showDescription?: boolean
  /** Show upcoming run times. Default true. */
  showUpcoming?: boolean
}

const FREQUENCIES = [
  { value: "hourly", label: "Every hour" },
  { value: "daily", label: "Every day" },
  { value: "weekly", label: "Every week" },
  { value: "monthly", label: "Every month" },
] as const

const DAY_ABBR = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"] as const

const timeFormat = new Intl.DateTimeFormat(undefined, {
  weekday: "short",
  month: "short",
  day: "numeric",
  hour: "2-digit",
  minute: "2-digit",
})

/**
 * A cron schedule field.
 *
 * The plain-English reading is the feature: a schedule nobody can read is a
 * schedule nobody can review. `minInterval` stops a job being scheduled every
 * second.
 */
export const CronInput = forwardRef<HTMLInputElement, CronInputProps>(
  function CronInput(
    {
      label,
      hint,
      layout = "expression",
      showDescription = true,
      showUpcoming = true,
      className,
      id: idProp,
      ...rest
    },
    ref,
  ) {
    const reactId = useId()
    const id = idProp ?? reactId

    const api = useCronInput({ ...rest, id })
    const {
      inputProps,
      ariaProps,
      containerProps,
      hiddenInputProps,
      ownsErrorUI,
      errorText,
      errorId,
      visible,
      description,
      valid,
      upcoming,
      builder,
      setFrequency,
      setTime,
      toggleDay,
      setDayOfMonth,
      value,
    } = api

    useImperativeHandle(
      ref,
      () =>
        inputProps.ref.current ??
        ({ focus: () => inputProps.ref.current?.focus() } as HTMLInputElement),
      [inputProps.ref],
    )

    const invalid = ariaProps["aria-invalid"] ? "true" : undefined
    const weekly = builder?.frequency === "weekly"
    const monthly = builder?.frequency === "monthly"

    return (
      <div className={`inputcn-field ${className ?? ""}`.trim()} {...containerProps}>
        {label === undefined ? null : (
          <label className="inputcn-label" htmlFor={id}>
            {label}
          </label>
        )}

        {layout === "builder" ? (
          builder ? (
            <div className="inputcn-cron-builder">
              <div className="inputcn-cron-row">
                <select
                  id={id}
                  className="inputcn-select"
                  value={builder.frequency}
                  disabled={rest.disabled}
                  aria-label="Frequency"
                  onChange={(e) =>
                    setFrequency(e.currentTarget.value as typeof builder.frequency)
                  }
                >
                  {FREQUENCIES.map((f) => (
                    <option key={f.value} value={f.value}>
                      {f.label}
                    </option>
                  ))}
                </select>

                <input
                  className="inputcn-input inputcn-cron-time"
                  type="time"
                  value={builder.time}
                  // Hourly repeats every hour, so an hour-of-day is meaningless.
                  disabled={rest.disabled || builder.frequency === "hourly"}
                  aria-label="Time of day"
                  onChange={(e) => setTime(e.currentTarget.value)}
                />

                {monthly ? (
                  <input
                    className="inputcn-input inputcn-cron-dom"
                    type="number"
                    min={1}
                    max={31}
                    value={builder.dayOfMonth}
                    disabled={rest.disabled}
                    aria-label="Day of month"
                    onChange={(e) => setDayOfMonth(Number(e.currentTarget.value))}
                  />
                ) : null}
              </div>

              {weekly ? (
                <div className="inputcn-daysrow" role="group" aria-label="Days of the week">
                  {DAY_ABBR.map((abbr, i) => (
                    <button
                      key={abbr}
                      type="button"
                      className="inputcn-day"
                      aria-pressed={builder.days.includes(i)}
                      aria-label={DAY_NAMES[i]}
                      disabled={rest.disabled}
                      onClick={() => toggleDay(i)}
                    >
                      {abbr}
                    </button>
                  ))}
                </div>
              ) : null}

              <div className="inputcn-exprbar">
                <span className="inputcn-exprbar-label">emits</span>
                <code>{value || "—"}</code>
              </div>
            </div>
          ) : (
            <p className="inputcn-hint">
              This schedule is more specific than the builder can show. Switch to the
              expression layout to edit it.
            </p>
          )
        ) : (
          <input
            {...inputProps}
            {...ariaProps}
            id={id}
            className="inputcn-input inputcn-mono"
            aria-label={rest["aria-label"]}
            aria-labelledby={rest["aria-labelledby"]}
          />
        )}

        {showDescription && description ? (
          <p className="inputcn-cron-reads" data-invalid={valid ? undefined : "true"}>
            {description}
          </p>
        ) : null}

        {showUpcoming && upcoming.length > 0 ? (
          <div className="inputcn-cron-next">
            <span className="inputcn-cron-next-label">Next runs</span>
            {upcoming.map((d) => (
              <span key={d.toISOString()} className="inputcn-cron-next-item">
                {timeFormat.format(d)}
              </span>
            ))}
          </div>
        ) : null}

        {ownsErrorUI && errorText ? (
          <p
            id={errorId}
            className={visible?.warning ? "inputcn-warning" : "inputcn-error"}
            // Stable rule name so a test can assert WHICH rule failed rather
            // than matching copy, which breaks on a rewrite or a locale change.
            data-rule={visible?.rule}
            role="alert"
          >
            {errorText}
          </p>
        ) : hint !== undefined ? (
          <p className="inputcn-hint">{hint}</p>
        ) : null}

        {hiddenInputProps ? <input {...hiddenInputProps} /> : null}
      </div>
    )
  },
)

"use client"

import { useCallback, useMemo, useRef, useState, type ClipboardEvent } from "react"

import { clipboardText, scrub } from "@inputcn/core/paste"
import type { BaseFieldProps, Rule } from "@inputcn/core/types"
import { useField, type UseFieldResult } from "@inputcn/core/use-field"
import { custom, required as requiredRule, rules } from "@inputcn/core/validity"

import {
  buildCron,
  describeCron,
  nextRuns,
  parseCron,
  shortestInterval,
  toBuilderState,
  type BuilderState,
  type Frequency,
} from "./cron"

/** Bounds accept human text so the prop reads like the rule: minInterval="5m". */
export type IntervalBound = number | string

export interface CronConstraints {
  /**
   * Reject schedules that fire more often than this. The constraint that earns
   * its keep — it stops someone scheduling a job every second and taking down
   * a worker queue.
   */
  minInterval?: IntervalBound
}

export interface UseCronInputOptions
  extends BaseFieldProps<string>,
    CronConstraints {
  /** How many upcoming runs to compute for the preview. Default 3. */
  previewCount?: number
}

export interface UseCronInputResult extends UseFieldResult<string> {
  /** Plain-English description of the current expression. */
  description: string
  valid: boolean
  /** Upcoming fire times. Empty when the expression is invalid. */
  upcoming: Date[]
  /** Builder state, or null when the expression is too complex to represent. */
  builder: BuilderState | null
  setFrequency: (f: Frequency) => void
  setTime: (hhmm: string) => void
  toggleDay: (day: number) => void
  setDayOfMonth: (day: number) => void
  inputProps: {
    ref: React.RefObject<HTMLInputElement | null>
    value: string
    onChange: (e: React.ChangeEvent<HTMLInputElement>) => void
    onPaste: (e: ClipboardEvent<HTMLInputElement>) => void
    spellCheck: false
    autoComplete: "off"
    disabled: boolean | undefined
    readOnly: boolean | undefined
    placeholder: string | undefined
  }
}

const EMPTY = ""
const DEFAULT_BUILDER: BuilderState = {
  frequency: "daily",
  time: "09:00",
  days: [1, 2, 3, 4, 5],
  dayOfMonth: 1,
}

/**
 * Quotes the offending field and what it accepts, rather than just "invalid".
 *
 * Built per call so the captured error lives in a closure, not at module
 * scope — module-level mutable state would leak between component instances
 * and, under SSR, between requests.
 */
function makeFieldRule(): Rule<string> {
  let captured: { field: string; value: string; reason: string } | null = null
  return {
    rule: "cronField",
    get params() {
      return captured ?? {}
    },
    test: (v: string) => {
      const p = parseCron(v)
      const first = p.errors[0]
      captured = first
        ? { field: first.field, value: first.value, reason: first.reason }
        : null
      return p.ok
    },
  } as Rule<string>
}

/** Interval bounds may be written as "5m"; resolve to seconds once. */
function toSeconds(bound: IntervalBound | undefined): number | undefined {
  if (bound === undefined) return undefined
  if (typeof bound === "number") return bound
  const m = /^(\d+(?:\.\d+)?)\s*(s|m|h|d)?$/i.exec(bound.trim())
  if (!m) return undefined
  const n = Number(m[1])
  const unit = (m[2] ?? "m").toLowerCase()
  return n * ({ s: 1, m: 60, h: 3600, d: 86_400 }[unit] ?? 60)
}

export function useCronInput(options: UseCronInputOptions): UseCronInputResult {
  const {
    minInterval,
    previewCount = 3,
    required,
    validate,
    disabled,
    readOnly,
    placeholder,
    ...base
  } = options

  const minSeconds = useMemo(() => toSeconds(minInterval), [minInterval])

  const ruleList = useMemo<ReadonlyArray<Rule<string>>>(
    () =>
      rules<string>(
        requiredRule<string>(required),
        makeFieldRule(),
        minSeconds !== undefined && {
          rule: "cronMinInterval",
          params: { minInterval: typeof minInterval === "string" ? minInterval : `${minSeconds}s` },
          test: (v) => {
            const p = parseCron(v)
            // An invalid expression is the format rule's problem, not this one's.
            return !p.ok || shortestInterval(v) >= minSeconds
          },
        },
        custom<string>(validate),
      ),
    [required, minSeconds, minInterval, validate],
  )

  const field = useField<string>({
    component: "CronInput",
    emptyValue: EMPTY,
    rules: ruleList,
    ...base,
    required,
    disabled,
    readOnly,
  })

  const { value, setValue } = field
  const ref = useRef<HTMLInputElement | null>(null)

  const parsed = useMemo(() => parseCron(value), [value])
  const description = useMemo(() => (value ? describeCron(value) : ""), [value])

  const upcoming = useMemo(
    () => (parsed.ok ? nextRuns(value, new Date(), previewCount) : []),
    [parsed.ok, value, previewCount],
  )

  /* ---------------- builder ---------------- */

  // Derived from the expression where possible, so the two layouts stay in
  // sync. Local state only fills the gaps the expression cannot express.
  const derived = useMemo(() => toBuilderState(value), [value])
  const [fallback, setFallback] = useState<BuilderState>(DEFAULT_BUILDER)
  const builder = derived ?? (value ? null : fallback)

  const applyBuilder = useCallback(
    (next: BuilderState) => {
      if (disabled || readOnly) return
      setFallback(next)
      setValue(buildCron(next))
    },
    [disabled, readOnly, setValue],
  )

  const current = derived ?? fallback

  const setFrequency = useCallback(
    (frequency: Frequency) => applyBuilder({ ...current, frequency }),
    [applyBuilder, current],
  )

  const setTime = useCallback(
    (time: string) => applyBuilder({ ...current, time }),
    [applyBuilder, current],
  )

  const toggleDay = useCallback(
    (day: number) => {
      const has = current.days.includes(day)
      const days = has ? current.days.filter((d) => d !== day) : [...current.days, day]
      applyBuilder({ ...current, days })
    },
    [applyBuilder, current],
  )

  const setDayOfMonth = useCallback(
    (dayOfMonth: number) => applyBuilder({ ...current, dayOfMonth }),
    [applyBuilder, current],
  )

  /* ---------------- text entry ---------------- */

  const onChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      if (disabled || readOnly) return
      setValue(e.currentTarget.value)
    },
    [disabled, readOnly, setValue],
  )

  const onPaste = useCallback(
    (e: ClipboardEvent<HTMLInputElement>) => {
      if (disabled || readOnly) return
      const text = clipboardText(e)
      if (!text) return
      e.preventDefault()
      // Cron expressions get copied out of YAML and crontabs with a command
      // trailing them; keep only the five schedule fields.
      const cleaned = scrub(text).replace(/^\s*[-*]\s*/, "")
      const parts = cleaned.split(/\s+/)
      setValue(parts.length > 5 && parseCron(parts.slice(0, 5).join(" ")).ok
        ? parts.slice(0, 5).join(" ")
        : cleaned)
    },
    [disabled, readOnly, setValue],
  )

  const inputProps = useMemo(
    () => ({
      ref,
      value,
      onChange,
      onPaste,
      spellCheck: false as const,
      autoComplete: "off" as const,
      disabled,
      readOnly,
      placeholder: placeholder ?? "0 9 * * 1-5",
    }),
    [value, onChange, onPaste, disabled, readOnly, placeholder],
  )

  return {
    ...field,
    description,
    valid: parsed.ok,
    upcoming,
    builder,
    setFrequency,
    setTime,
    toggleDay,
    setDayOfMonth,
    inputProps,
  }
}

/**
 * Cron expression parsing, description and scheduling. Framework-free.
 *
 * Canonical value is the five-field expression: `"0 9 * * 1-5"`.
 *
 * Two things here that nobody else in this category does:
 *   • a plain-English description, so a non-engineer can verify a schedule
 *     without asking one
 *   • `minInterval`, so nobody accidentally schedules a job every second and
 *     takes down a worker queue
 */

import { scrub } from "@inputcn/core/paste"

export type CronField = "minute" | "hour" | "dayOfMonth" | "month" | "dayOfWeek"

export const FIELD_ORDER: readonly CronField[] = [
  "minute",
  "hour",
  "dayOfMonth",
  "month",
  "dayOfWeek",
]

interface FieldSpec {
  min: number
  max: number
  /** Names accepted in place of numbers, lowercase, index-aligned to `min`. */
  names?: readonly string[]
}

const SPECS: Readonly<Record<CronField, FieldSpec>> = {
  minute: { min: 0, max: 59 },
  hour: { min: 0, max: 23 },
  dayOfMonth: { min: 1, max: 31 },
  month: {
    min: 1,
    max: 12,
    names: ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"],
  },
  // 0 and 7 both mean Sunday, which the parser normalises.
  dayOfWeek: { min: 0, max: 7, names: ["sun", "mon", "tue", "wed", "thu", "fri", "sat"] },
}

export const DAY_NAMES = [
  "Sunday",
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday",
] as const

export const MONTH_NAMES = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
] as const

/** Named shorthands people expect to work. */
export const ALIASES: Readonly<Record<string, string>> = {
  "@yearly": "0 0 1 1 *",
  "@annually": "0 0 1 1 *",
  "@monthly": "0 0 1 * *",
  "@weekly": "0 0 * * 0",
  "@daily": "0 0 * * *",
  "@midnight": "0 0 * * *",
  "@hourly": "0 * * * *",
}

export interface FieldError {
  field: CronField
  value: string
  reason: string
}

export interface ParsedCron {
  ok: boolean
  /** The normalised five-field expression. */
  expression: string
  /** Matching values per field, sorted ascending. Empty when invalid. */
  values: Record<CronField, number[]>
  errors: FieldError[]
}

const RANGE_RE = /^(\d+|[a-z]{3})(?:-(\d+|[a-z]{3}))?(?:\/(\d+))?$/i
const STAR_RE = /^\*(?:\/(\d+))?$/

function resolveToken(token: string, spec: FieldSpec): number | null {
  const named = spec.names?.indexOf(token.toLowerCase())
  if (named !== undefined && named !== -1) return named + spec.min
  const n = Number(token)
  return Number.isInteger(n) ? n : null
}

/** Expand one field into the concrete values it matches. */
function expandField(raw: string, field: CronField): { values: number[]; error?: string } {
  const spec = SPECS[field]
  const out = new Set<number>()

  for (const part of raw.split(",")) {
    const star = STAR_RE.exec(part)
    if (star) {
      const step = star[1] === undefined ? 1 : Number(star[1])
      if (step < 1) return { values: [], error: `step must be 1 or more` }
      for (let v = spec.min; v <= spec.max; v += step) out.add(v)
      continue
    }

    const m = RANGE_RE.exec(part)
    if (!m) return { values: [], error: `"${part}" is not a number, range or step` }

    const from = resolveToken(m[1]!, spec)
    if (from === null) return { values: [], error: `"${m[1]}" is not a valid value` }

    const to = m[2] === undefined ? from : resolveToken(m[2], spec)
    if (to === null) return { values: [], error: `"${m[2]}" is not a valid value` }

    const step = m[3] === undefined ? 1 : Number(m[3])
    if (step < 1) return { values: [], error: `step must be 1 or more` }

    if (from < spec.min || to > spec.max) {
      return { values: [], error: `accepts ${spec.min}-${spec.max}` }
    }
    if (to < from) return { values: [], error: `range runs backwards` }

    for (let v = from; v <= to; v += step) out.add(v)
  }

  // Sunday is both 0 and 7; collapse so comparisons are simple.
  if (field === "dayOfWeek" && out.has(7)) {
    out.delete(7)
    out.add(0)
  }

  return { values: [...out].sort((a, b) => a - b) }
}

const EMPTY_VALUES = (): Record<CronField, number[]> => ({
  minute: [],
  hour: [],
  dayOfMonth: [],
  month: [],
  dayOfWeek: [],
})

/** Parse and validate a cron expression. */
export function parseCron(input: string): ParsedCron {
  const text = scrub(input).toLowerCase()
  const expanded = ALIASES[text] ?? text
  const parts = expanded.split(/\s+/).filter(Boolean)

  if (parts.length !== 5) {
    return {
      ok: false,
      expression: expanded,
      values: EMPTY_VALUES(),
      errors: [
        {
          field: "minute",
          value: expanded,
          reason: `needs exactly 5 fields, found ${parts.length}`,
        },
      ],
    }
  }

  const values = EMPTY_VALUES()
  const errors: FieldError[] = []

  FIELD_ORDER.forEach((field, i) => {
    const raw = parts[i]!
    const { values: vals, error } = expandField(raw, field)
    if (error) errors.push({ field, value: raw, reason: error })
    else values[field] = vals
  })

  return { ok: errors.length === 0, expression: parts.join(" "), values, errors }
}

/* ------------------------------------------------------------------ *
 * Plain English
 * ------------------------------------------------------------------ */

function listNames(values: number[], names: readonly string[]): string {
  const picked = values.map((v) => names[v] ?? String(v))
  if (picked.length === 1) return picked[0]!
  if (picked.length === 2) return `${picked[0]} and ${picked[1]}`
  return `${picked.slice(0, -1).join(", ")} and ${picked.at(-1)}`
}

/**
 * The common step between values, when they are evenly spaced across the
 * field's full range. Lets "0,15,30,45" be described as "every 15 minutes"
 * rather than listed out.
 */
function evenStep(values: number[], min: number, max: number): number | null {
  if (values.length < 3 || values[0] !== min) return null
  const step = values[1]! - values[0]!
  if (step < 2) return null
  for (let i = 1; i < values.length; i++) {
    if (values[i]! - values[i - 1]! !== step) return null
  }
  // The run must reach the end of the field, or it is a partial range and
  // "every N" would overstate it.
  return values.at(-1)! + step > max ? step : null
}

/** True when the values form an unbroken run — "Monday through Friday". */
function isContiguous(values: number[]): boolean {
  if (values.length < 3) return false
  for (let i = 1; i < values.length; i++) {
    if (values[i]! !== values[i - 1]! + 1) return false
  }
  return true
}

const pad = (n: number) => String(n).padStart(2, "0")

/**
 * Describe a schedule in a sentence a non-engineer can check.
 * This is the feature — a cron field nobody can read is a cron field nobody
 * can review.
 */
export function describeCron(input: string): string {
  const parsed = parseCron(input)
  if (!parsed.ok) {
    const first = parsed.errors[0]
    return first ? `Invalid: the ${labelOf(first.field)} field ${first.reason}` : "Invalid schedule"
  }

  const { minute, hour, dayOfMonth, month, dayOfWeek } = parsed.values
  const allMinutes = minute.length === 60
  const allHours = hour.length === 24
  const allDom = dayOfMonth.length === 31
  const allMonths = month.length === 12
  const allDow = dayOfWeek.length === 7

  const minuteStep = evenStep(minute, 0, 59)

  let when: string
  if (allMinutes && allHours) {
    when = "Every minute"
  } else if (minuteStep !== null && allHours) {
    when = `Every ${minuteStep} minutes`
  } else if (minuteStep !== null) {
    when = `Every ${minuteStep} minutes, during ${listNames(hour, hour.map((h) => `${pad(h)}:00`))}`
  } else if (allMinutes) {
    when = `Every minute past ${listNames(hour.map((h) => h), hour.map((h) => `${pad(h)}:00`))}`
  } else if (allHours) {
    when =
      minute.length === 1
        ? `At minute ${minute[0]} of every hour`
        : `At minutes ${minute.join(", ")} of every hour`
  } else if (minute.length === 1 && hour.length === 1) {
    when = `At ${pad(hour[0]!)}:${pad(minute[0]!)}`
  } else if (minute.length === 1) {
    when = `At ${minute[0]} minutes past ${listNames(hour, hour.map((h) => `${pad(h)}:00`))}`
  } else {
    when = `At ${minute.length} times per hour, during ${hour.length} hours`
  }

  const clauses: string[] = []

  if (!allDow) {
    clauses.push(
      isContiguous(dayOfWeek)
        ? `${DAY_NAMES[dayOfWeek[0]!]} through ${DAY_NAMES[dayOfWeek.at(-1)!]}`
        : `on ${listNames(dayOfWeek, DAY_NAMES)}`,
    )
  }

  if (!allDom) {
    clauses.push(
      isContiguous(dayOfMonth)
        ? `on days ${dayOfMonth[0]}–${dayOfMonth.at(-1)} of the month`
        : `on day ${dayOfMonth.join(", ")} of the month`,
    )
  }

  if (!allMonths) {
    clauses.push(`in ${listNames(month.map((m) => m - 1), MONTH_NAMES)}`)
  }

  return clauses.length ? `${when}, ${clauses.join(", ")}` : when
}

function labelOf(field: CronField): string {
  return field === "dayOfMonth"
    ? "day-of-month"
    : field === "dayOfWeek"
      ? "day-of-week"
      : field
}

/* ------------------------------------------------------------------ *
 * Scheduling
 * ------------------------------------------------------------------ */

/**
 * The next `count` fire times after `from`.
 *
 * Deliberately a bounded minute-by-minute scan rather than a date solver: it
 * is simple enough to be obviously correct, and the horizon caps the cost. A
 * schedule that fires less often than once every 4 years returns fewer
 * results rather than hanging.
 */
export function nextRuns(input: string, from = new Date(), count = 3): Date[] {
  const parsed = parseCron(input)
  if (!parsed.ok) return []

  const { minute, hour, dayOfMonth, month, dayOfWeek } = parsed.values
  const mins = new Set(minute)
  const hrs = new Set(hour)
  const doms = new Set(dayOfMonth)
  const months = new Set(month)
  const dows = new Set(dayOfWeek)

  // A restricted day-of-month and day-of-week are OR'd, per POSIX cron.
  const domRestricted = dayOfMonth.length !== 31
  const dowRestricted = dayOfWeek.length !== 7

  const out: Date[] = []
  const d = new Date(from.getTime())
  d.setSeconds(0, 0)

  const HORIZON = 60 * 24 * 366 * 4 // four years of minutes
  for (let i = 0; i < HORIZON && out.length < count; i++) {
    d.setMinutes(d.getMinutes() + 1)

    if (!mins.has(d.getMinutes())) continue
    if (!hrs.has(d.getHours())) continue
    if (!months.has(d.getMonth() + 1)) continue

    const domOk = doms.has(d.getDate())
    const dowOk = dows.has(d.getDay())
    const dayOk =
      domRestricted && dowRestricted ? domOk || dowOk
      : domRestricted ? domOk
      : dowRestricted ? dowOk
      : true
    if (!dayOk) continue

    out.push(new Date(d.getTime()))
  }

  return out
}

/**
 * Shortest gap between consecutive runs, in seconds. `Infinity` when the
 * schedule fires less than twice inside the sampling window.
 *
 * Powers `minInterval` — the constraint that stops someone scheduling a job
 * every second.
 */
export function shortestInterval(input: string, from = new Date()): number {
  const runs = nextRuns(input, from, 12)
  if (runs.length < 2) return Number.POSITIVE_INFINITY

  let shortest = Number.POSITIVE_INFINITY
  for (let i = 1; i < runs.length; i++) {
    const gap = (runs[i]!.getTime() - runs[i - 1]!.getTime()) / 1000
    if (gap < shortest) shortest = gap
  }
  return shortest
}

/* ------------------------------------------------------------------ *
 * Builder
 * ------------------------------------------------------------------ */

export type Frequency = "hourly" | "daily" | "weekly" | "monthly"

export interface BuilderState {
  frequency: Frequency
  /** "HH:MM". Ignored for hourly. */
  time: string
  /** 0–6, Sunday first. Used by weekly. */
  days: readonly number[]
  /** 1–31. Used by monthly. */
  dayOfMonth: number
}

/** Compose an expression from the visual builder's state. */
export function buildCron({ frequency, time, days, dayOfMonth }: BuilderState): string {
  const [h = 0, m = 0] = time.split(":").map(Number)
  switch (frequency) {
    case "hourly":
      return `${m} * * * *`
    case "daily":
      return `${m} ${h} * * *`
    case "monthly":
      return `${m} ${h} ${dayOfMonth} * *`
    case "weekly":
      return `${m} ${h} * * ${days.length ? [...days].sort((a, b) => a - b).join(",") : "*"}`
  }
}

/**
 * Best-effort inverse of `buildCron`, so switching from the expression layout
 * to the builder does not silently discard the schedule.
 */
export function toBuilderState(input: string): BuilderState | null {
  const parsed = parseCron(input)
  if (!parsed.ok) return null

  const { minute, hour, dayOfMonth, month, dayOfWeek } = parsed.values
  if (minute.length !== 1 || month.length !== 12) return null

  const m = minute[0]!
  const time = (hh: number) => `${pad(hh)}:${pad(m)}`

  if (hour.length === 24 && dayOfMonth.length === 31 && dayOfWeek.length === 7) {
    return { frequency: "hourly", time: time(0), days: [], dayOfMonth: 1 }
  }
  if (hour.length !== 1) return null
  const h = hour[0]!

  if (dayOfMonth.length === 31 && dayOfWeek.length === 7) {
    return { frequency: "daily", time: time(h), days: [], dayOfMonth: 1 }
  }
  if (dayOfMonth.length === 31) {
    return { frequency: "weekly", time: time(h), days: dayOfWeek, dayOfMonth: 1 }
  }
  if (dayOfMonth.length === 1 && dayOfWeek.length === 7) {
    return { frequency: "monthly", time: time(h), days: [], dayOfMonth: dayOfMonth[0]! }
  }
  return null
}
